def match(self, cfn: Template) -> RuleMatches:
    matches = []
    ref_conditions = {}

    conditions = cfn.template.get('Conditions', {})
    if conditions:
        # Get all "If's" that reference a Condition
        iftrees = cfn.search_deep_keys('Fn::If')

        for iftree in iftrees:
