            if condtree[0] == 'Conditions':
                if isinstance(condtree[-1], (str)):
                    ref_conditions[condtree[-1]] = True

        # Get resource\'s Conditions
        for resource_name, resource_values in cfn.get_resources().items():
            if 'Condition' in resource_values and not self._contains_placeholder(resource_values['Condition']):
                ref_conditions[resource_values['Condition']] = True

        # Get Output Conditions
        for output_name, output_values in cfn.template.get('Outputs', {}).items():
            if 'Condition' in output_values and not self._contains_placeholder(output_values['Condition']):
                ref_conditions[output_values['Condition']] = True

        # Check if the conditions are used
        for condname, _ in conditions.items():
            if condname not in ref_conditions:
                message = "Condition {0} not used"
                matches.append(
                    RuleMatch([
                        'Conditions',
                        condname,
                    ],
                    message.format(condname),
                )

    return matches
